def subtract(a, b):
    # Filter out empty intervals and collect all events
    a_intervals = [interval for interval in a if interval[0] < interval[1]]
    b_intervals = [interval for interval in b if interval[0] < interval[1]]

    if not a_intervals:
        return []

    # Merge overlapping intervals in a
    a_merged = []
    for start, end in sorted(a_intervals):
        if a_merged and a_merged[-1][1] >= start:
            a_merged[-1][1] = max(a_merged[-1][1], end)
        else:
            a_merged.append([start, end])

    # Merge overlapping intervals in b
    b_merged = []
    for start, end in sorted(b_intervals):
        if b_merged and b_merged[-1][1] >= start:
            b_merged[-1][1] = max(b_merged[-1][1], end)
        else:
            b_merged.append([start, end])

    if not b_merged:
        return a_merged

    result = []

    for a_start, a_end in a_merged:
        current_ranges = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            next_ranges = []
            for curr_start, curr_end in current_ranges:
                # No overlap
                if curr_end <= b_start or curr_start >= b_end:
                    next_ranges.append([curr_start, curr_end])
                else:
                    # Add left part before b_start
                    if curr_start < b_start:
                        next_ranges.append([curr_start, b_start])
                    # Add right part after b_end
                    if curr_end > b_end:
                        next_ranges.append([b_end, curr_end])
            current_ranges = next_ranges

        result.extend(current_ranges)

    # Merge adjacent ranges in result
    if not result:
        return []

    result.sort()
    merged_result = []
    for start, end in result:
        if merged_result and merged_result[-1][1] >= start:
            merged_result[-1][1] = max(merged_result[-1][1], end)
        else:
            merged_result.append([start, end])

    return merged_result

